// Ported from the Node app's Sequelize model Board (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class BoardConfiguration : IEntityTypeConfiguration<Board>
{
    public void Configure(EntityTypeBuilder<Board> builder)
    {
        builder.ToTable("boards");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Code).HasColumnName("code").HasColumnType("nvarchar(20)").HasMaxLength(20).IsRequired();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(40)").HasMaxLength(40).IsRequired();
        builder.Property(e => e.IsEnabled).HasColumnName("is_enabled");
        builder.HasIndex(e => e.Code).IsUnique();
        builder.HasIndex(e => e.Name).IsUnique();
        builder.HasMany(e => e.StudentBoardRegistrations).WithOne().HasForeignKey(c => c.BoardId).OnDelete(DeleteBehavior.NoAction);
    }
}
